<script lang="ts">import type {ActivityCard} from '../generated/ActivityCard';import ZoneStrip from './ZoneStrip.svelte';import {clock,elapsed} from '../format';let {activity,open}:{activity:ActivityCard,open:()=>void}=$props();</script><button class="activity" onclick={open}><span class="act-ico">{activity.icon==='run'?'♧':activity.icon==='bike'?'◉':'ϟ'}</span><span class="act-main"><b>{activity.name}</b><small>{clock(activity.startLocal)} · {activity.distanceKm!=null?activity.distanceKm+' km · ':''}{elapsed(activity.durationS)}</small></span>{#if activity.load!=null}<span class="act-load"><b class="n">{Math.round(activity.load)}</b><small>Load</small></span>{/if}</button>{#if activity.zoneSeconds?.length}<ZoneStrip seconds={activity.zoneSeconds}/>{/if}